 IF (SELECT COUNT(*) FROM information_schema.TABLES WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME IN ('tradeskill_recipe','tradeskill_recipe_entries','items') AND ENGINE='InnoDB')<>3 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC157 InnoDB foundation mismatch'; END IF;
 IF (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe')<>16 OR (SELECT COUNT(*) FROM information_schema.COLUMNS WHERE TABLE_SCHEMA=DATABASE() AND TABLE_NAME='tradeskill_recipe_entries')<>8 THEN SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT='RRC157 recipe schema column-count mismatch'; END IF;
 CREATE TEMPORARY TABLE rrc157_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc157_entries LIKE tradeskill_recipe_entries;
 CREATE TEMPORARY TABLE rrc157_items(id INT PRIMARY KEY,name VARCHAR(64) NOT NULL) ENGINE=InnoDB;
 CREATE TEMPORARY TABLE rrc157_peer_recipes LIKE tradeskill_recipe;
 CREATE TEMPORARY TABLE rrc157_peer_entries LIKE tradeskill_recipe_entries;
